package com.meetspace.controller; import com.meetspace.dto.*; import com.meetspace.dto.AdminDtos.*; import com.meetspace.service.AdminService; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") public class AdminController { private final AdminService service; public AdminController(AdminService service){this.service=service;} @GetMapping("/dashboard") ApiResponse<Dashboard> dashboard(){return ApiResponse.ok("Dashboard retrieved",service.dashboard());} @GetMapping("/employees") ApiResponse<List<Employee>> employees(){return ApiResponse.ok("Employees retrieved",service.employees());} @GetMapping("/bookings") ApiResponse<List<Booking>> bookings(){return ApiResponse.ok("Bookings retrieved",service.bookings());} }
